describe('Image Upload - Small Dimensions Error', () => {
  beforeEach(() => {
    cy.visit('/upload');
  });

  it('should display error message when uploading image with small dimensions', () => {
    // Intercept the upload API call
    cy.intercept('POST', '/api/upload').as('uploadImage');

    // Get the file input element
    cy.get('[data-testid="image-upload-input"]').selectFile('cypress/fixtures/small-image.png', { force: true });

    // Click the upload button
    cy.get('[data-testid="upload-button"]').click();

    // Wait for the API call
    cy.wait('@uploadImage');

    // Verify error message is displayed
    cy.get('[data-testid="error-message"]')
      .should('be.visible')
      .should('contain', 'Image dimensions must be at least 100x100 pixels');

    // Verify error icon is visible
    cy.get('[data-testid="error-icon"]')
      .should('be.visible');

    // Verify upload button is still enabled for retry
    cy.get('[data-testid="upload-button"]')
      .should('not.be.disabled');
  });

  it('should allow upload when image dimensions meet minimum requirements', () => {
    // Intercept the upload API call
    cy.intercept('POST', '/api/upload').as('uploadImage');

    // Get the file input element
    cy.get('[data-testid="image-upload-input"]').selectFile('cypress/fixtures/valid-image.png', { force: true });

    // Click the upload button
    cy.get('[data-testid="upload-button"]').click();

    // Wait for the API call
    cy.wait('@uploadImage');

    // Verify success message is displayed
    cy.get('[data-testid="success-message"]')
      .should('be.visible')
      .should('contain', 'Image uploaded successfully');

    // Verify error message is not visible
    cy.get('[data-testid="error-message"]')
      .should('not.exist');

    // Verify success icon is visible
    cy.get('[data-testid="success-icon"]')
      .should('be.visible');
  });
});
